tool_use_result.content:
/* ===== RESET & BASE ===== */
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,.1), 0 2px 4px -2px rgba(0,0,0,.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,.1), 0 4px 6px -4px rgba(0,0,0,.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,.1), 0 8px 10px -6px rgba(0,0,0,.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: .3s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: 'Inter', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4 { font-family: 'Plus Jakarta Sans', 'Inter', sans-serif; font-weight: 700; line-height: 1.15; }
h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; }

/* ===== LAYOUT ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section--gray { background: var(--gray-50); }

/* ===== ANIMATIONS ===== */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slideIn {
  from { opacity: 0; transform: translateX(20px); }
  to { opacity: 1; transform: translateX(0); }
}
.animate-on-scroll { opacity: 0; transform: translateY(30px); transition: opacity .6s ease, transform .6s ease; }
.animate-on-scroll.visible { opacity: 1; transform: translateY(0); }

/* ===== NAVBAR ===== */
.navbar {
  position: sticky; top: 0; z-index: 1000;
  background: rgba(255,255,255,.95); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.navbar.scrolled { box-shadow: var(--shadow-md); }
.navbar__inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 72px; max-width: 1200px; margin: 0 auto; padding: 0 24px;
}
.navbar__logo {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800; font-size: 1.5rem; color: var(--black);
  display: flex; align-items: center; gap: 8px;
}
.navbar__logo-icon {
  width: 36px; height: 36px; background: var(--lime);
  border-radius: 8px; display: flex; align-items: center; justify-content: center;
  font-weight: 900; color: var(--black); font-size: 1.2rem;
}
.navbar__links { display: flex; align-items: center; gap: 32px; }
.navbar__link {
  font-size: .938rem; font-weight: 500; color: var(--gray-600);
  transition: color var(--transition); position: relative;
}
.navbar__link:hover { color: var(--black); }
.navbar__link::after {
  content: ''; position: absolute; bottom: -4px; left: 0;
  width: 0; height: 2px; background: var(--lime);
  transition: width var(--transition);
}
.navbar__link:hover::after { width: 100%; }
.navbar__cta {
  background: var(--black); color: var(--white);
  padding: 10px 24px; border-radius: 50px;
  font-weight: 600; font-size: .875rem;
  transition: all var(--transition);
  display: inline-flex; align-items: center; gap: 6px;
}
.navbar__cta:hover { background: var(--burgundy); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.navbar__mobile-toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.navbar__mobile-toggle span { display: block; width: 24px; height: 2px; background: var(--black); transition: var(--transition); border-radius: 2px; }

/* ===== HERO ===== */
.hero {
  padding: 80px 0 60px;
  background: linear-gradient(180deg, var(--white) 0%, var(--gray-50) 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: -200px; right: -200px;
  width: 600px; height: 600px; border-radius: 50%;
  background: radial-gradient(circle, rgba(230,255,50,.12) 0%, transparent 70%);
  pointer-events: none;
}
.hero__content { text-align: center; max-width: 800px; margin: 0 auto 48px; position: relative; z-index: 1; }
.hero__title { margin-bottom: 20px; color: var(--black); }
.hero__title span { color: var(--burgundy); }
.hero__subtitle { font-size: clamp(1rem, 2vw, 1.25rem); color: var(--gray-600); margin-bottom: 32px; max-width: 640px; margin-left: auto; margin-right: auto; }
.hero__actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 32px; border-radius: 50px;
  font-weight: 600; font-size: 1rem;
  transition: all var(--transition);
}
.btn--primary { background: var(--black); color: var(--white); }
.btn--primary:hover { background: var(--burgundy); transform: translateY(-2px); box-shadow: var(--shadow-xl); }
.btn--secondary { background: var(--white); color: var(--black); border: 2px solid var(--gray-200); }
.btn--secondary:hover { border-color: var(--black); transform: translateY(-2px); }
.btn--lime { background: var(--lime); color: var(--black); }
.btn--lime:hover { background: #d4eb2e; transform: translateY(-2px); box-shadow: var(--shadow-lg); }

/* Hero Tab Switch */
.hero__tabs { margin-top: 40px; }
.hero__tab-nav { display: flex; justify-content: center; gap: 8px; margin-bottom: 24px; }
.hero__tab-btn {
  padding: 10px 28px; border-radius: 50px;
  font-weight: 600; font-size: .875rem;
  background: var(--white); color: var(--gray-600);
  border: 2px solid var(--gray-200);
  transition: all var(--transition);
}
.hero__tab-btn.active { background: var(--black); color: var(--white); border-color: var(--black); }
.hero__tab-btn:hover:not(.active) { border-color: var(--gray-400); }
.hero__tab-panel { display: none; animation: fadeIn .4s ease; }
.hero__tab-panel.active { display: block; }
.hero__preview {
  background: var(--white); border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200); box-shadow: var(--shadow-xl);
  overflow: hidden; max-width: 900px; margin: 0 auto;
}
.hero__preview-header {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 20px; background: var(--gray-50);
  border-bottom: 1px solid var(--gray-200);
}
.hero__preview-dot { width: 10px; height: 10px; border-radius: 50%; }
.hero__preview-dot--red { background: #EF4444; }
.hero__preview-dot--yellow { background: #F59E0B; }
.hero__preview-dot--green { background: #10B981; }
.hero__preview-body { padding: 32px; min-height: 280px; }
.hero__preview-grid { display: grid; grid-template-columns: 220px 1fr; gap: 24px; }
.hero__preview-sidebar { border-right: 1px solid var(--gray-200); padding-right: 24px; }
.hero__preview-sidebar-item {
  padding: 10px 12px; border-radius: var(--radius-sm);
  font-size: .813rem; color: var(--gray-600); margin-bottom: 4px;
  transition: all var(--transition); cursor: pointer;
}
.hero__preview-sidebar-item.active { background: var(--lime); color: var(--black); font-weight: 600; }
.hero__preview-main h4 { font-size: 1rem; margin-bottom: 12px; }
.hero__preview-main p { font-size: .813rem; color: var(--gray-500); line-height: 1.6; }
.hero__preview-student { text-align: center; }
.hero__preview-student h4 { font-size: 1.25rem; margin-bottom: 16px; }
.hero__preview-progress { background: var(--gray-100); border-radius: 50px; height: 8px; margin: 16px 0; overflow: hidden; }
.hero__preview-progress-bar { height: 100%; background: var(--lime); border-radius: 50px; width: 65%; }

/* ===== STATS BAR ===== */
.stats-bar {
  background: var(--black); padding: 48px 0;
}
.stats-bar__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; text-align: center; }
.stats-bar__item { animation: fadeUp .6s ease both; }
.stats-bar__number {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(2rem, 4vw, 3.5rem); font-weight: 800;
  color: var(--lime); margin-bottom: 8px;
}
.stats-bar__label { font-size: 1rem; color: rgba(255,255,255,.7); font-weight: 500; }

/* ===== PRODUCTS ===== */
.products__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 24px; }
.product-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition); position: relative; overflow: hidden;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); border-color: transparent; }
.product-card__icon {
  width: 56px; height: 56px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; margin-bottom: 20px;
}
.product-card__icon--courses { background: #EEF2FF; color: #4F46E5; }
.product-card__icon--coaching { background: #FEF3C7; color: #D97706; }
.product-card__icon--downloads { background: #ECFDF5; color: #059669; }
.product-card__icon--memberships { background: #FDF2F8; color: #DB2777; }
.product-card__title { margin-bottom: 12px; }
.product-card__desc { color: var(--gray-500); font-size: .938rem; line-height: 1.6; margin-bottom: 20px; }
.product-card__link {
  font-weight: 600; font-size: .875rem; color: var(--black);
  display: inline-flex; align-items: center; gap: 6px;
  transition: gap var(--transition);
}
.product-card__link:hover { gap: 10px; }
.product-card::after {
  content: ''; position: absolute; top: 0; left: 0;
  width: 100%; height: 3px; background: var(--lime);
  transform: scaleX(0); transform-origin: left;
  transition: transform var(--transition);
}
.product-card:hover::after { transform: scaleX(1); }

/* ===== WHY CHOOSE US (Tabs) ===== */
.why-choose__tabs { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 48px; }
.why-choose__tab-btn {
  padding: 12px 24px; border-radius: 50px;
  font-weight: 600; font-size: .875rem;
  background: var(--white); color: var(--gray-600);
  border: 2px solid var(--gray-200);
  transition: all var(--transition);
}
.why-choose__tab-btn.active { background: var(--lime); color: var(--black); border-color: var(--lime); }
.why-choose__tab-btn:hover:not(.active) { border-color: var(--gray-400); color: var(--black); }
.why-choose__panel { display: none; animation: fadeIn .4s ease; }
.why-choose__panel.active { display: block; }
.why-choose__features { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 20px; }
.why-choose__feature {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 16px; border-radius: var(--radius-md);
  background: var(--gray-50); transition: all var(--transition);
}
.why-choose__feature:hover { background: var(--lime); }
.why-choose__feature-icon { flex-shrink: 0; width: 24px; height: 24px; color: var(--burgundy); }
.why-choose__feature-text { font-weight: 500; font-size: .938rem; }

/* ===== GLOBAL SCALE ===== */
.global-scale { text-align: center; }
.global-scale__map {
  width: 100%; max-width: 800px; margin: 40px auto;
  position: relative; height: 300px;
  background: var(--gray-100); border-radius: var(--radius-lg);
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.global-scale__map-text { font-size: 1.5rem; font-weight: 700; color: var(--gray-400); }
.global-scale__dots { display: flex; flex-wrap: wrap; justify-content: center; gap: 16px; margin-top: 32px; }
.global-scale__dot-item {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 20px; background: var(--white);
  border: 1px solid var(--gray-200); border-radius: 50px;
  font-size: .875rem; font-weight: 500;
}
.global-scale__dot-indicator { width: 8px; height: 8px; border-radius: 50%; background: var(--lime); }

/* ===== AI AUTOMATIONS ===== */
.ai-automations__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.ai-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.ai-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.ai-card__badge {
  display: inline-block; padding: 4px 12px; border-radius: 50px;
  background: var(--lime); color: var(--black);
  font-size: .75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: .05em; margin-bottom: 16px;
}
.ai-card__title { margin-bottom: 12px; }
.ai-card__desc { color: var(--gray-500); font-size: .938rem; line-height: 1.6; }

/* ===== TESTIMONIALS ===== */
.testimonials { overflow: hidden; }
.testimonials__header { text-align: center; margin-bottom: 48px; }
.testimonials__carousel { position: relative; }
.testimonials__track {
  display: flex; gap: 24px;
  transition: transform .5s cubic-bezier(.4,0,.2,1);
}
.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  min-height: 260px; display: flex; flex-direction: column;
  transition: all var(--transition);
}
.testimonial-card:hover { box-shadow: var(--shadow-lg); }
.testimonial-card__quote {
  font-size: .938rem; color: var(--gray-600); line-height: 1.7;
  flex: 1; margin-bottom: 20px; position: relative;
}
.testimonial-card__quote::before {
  content: '\201C'; font-size: 3rem; color: var(--lime);
  position: absolute; top: -16px; left: -4px;
  font-family: Georgia, serif; line-height: 1;
}
.testimonial-card__quote p { padding-left: 20px; }
.testimonial-card__author { display: flex; align-items: center; gap: 12px; }
.testimonial-card__avatar {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: .875rem; color: var(--gray-500);
}
.testimonial-card__name { font-weight: 600; font-size: .875rem; }
.testimonial-card__role { font-size: .813rem; color: var(--gray-400); }
.testimonials__nav { display: flex; justify-content: center; gap: 12px; margin-top: 32px; }
.testimonials__nav-btn {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); border: 2px solid var(--gray-200);
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition); font-size: 1.2rem; color: var(--gray-600);
}
.testimonials__nav-btn:hover { background: var(--black); color: var(--white); border-color: var(--black); }

/* ===== PRICING ===== */
.pricing__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 20px; }
.pricing-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 2px solid var(--gray-200);
  transition: all var(--transition); position: relative;
}
.pricing-card--featured { border-color: var(--lime); }
.pricing-card--featured::before {
  content: 'Most Popular'; position: absolute; top: -12px; left: 50%;
  transform: translateX(-50%); background: var(--lime);
  padding: 4px 16px; border-radius: 50px;
  font-size: .75rem; font-weight: 700; color: var(--black);
}
.pricing-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.pricing-card__name { font-size: 1.125rem; font-weight: 700; margin-bottom: 8px; }
.pricing-card__price { font-size: 2.5rem; font-weight: 800; margin-bottom: 4px; }
.pricing-card__price span { font-size: 1rem; font-weight: 400; color: var(--gray-500); }
.pricing-card__fee { font-size: .813rem; color: var(--gray-400); margin-bottom: 20px; }
.pricing-card__features { margin-bottom: 24px; }
.pricing-card__feature {
  display: flex; align-items: flex-start; gap: 10px;
  font-size: .875rem; color: var(--gray-600);
  margin-bottom: 10px; line-height: 1.5;
}
.pricing-card__check { flex-shrink: 0; color: var(--lime); font-weight: 700; font-size: 1rem; }
.pricing-card__btn {
  width: 100%; padding: 12px; border-radius: 50px;
  font-weight: 600; font-size: .875rem; text-align: center;
  transition: all var(--transition);
}
.pricing-card__btn--primary { background: var(--black); color: var(--white); }
.pricing-card__btn--primary:hover { background: var(--burgundy); }
.pricing-card__btn--lime { background: var(--lime); color: var(--black); }
.pricing-card__btn--lime:hover { background: #d4eb2e; }
.pricing__note { text-align: center; margin-top: 32px; font-size: .875rem; color: var(--gray-500); }

/* ===== INTEGRATIONS ===== */
.integrations__header { text-align: center; margin-bottom: 48px; }
.integrations__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 16px; }
.integration-item {
  display: flex; flex-direction: column; align-items: center;
  gap: 10px; padding: 24px 16px; background: var(--white);
  border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  transition: all var(--transition);
}
.integration-item:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: var(--gray-300); }
.integration-item__logo {
  width: 48px; height: 48px; border-radius: var(--radius-sm);
  background: var(--gray-50); display: flex; align-items: center;
  justify-content: center; font-weight: 800; font-size: .75rem;
  color: var(--gray-600);
}
.integration-item__name { font-size: .813rem; font-weight: 600; color: var(--gray-700); text-align: center; }

/* ===== FAQ ===== */
.faq__list { max-width: 760px; margin: 0 auto; }
.faq__item {
  border-bottom: 1px solid var(--gray-200);
  overflow: hidden;
}
.faq__question {
  width: 100%; text-align: left; padding: 24px 0;
  font-size: 1.063rem; font-weight: 600; color: var(--gray-900);
  display: flex; justify-content: space-between; align-items: center;
  transition: color var(--transition);
}
.faq__question:hover { color: var(--burgundy); }
.faq__icon {
  width: 28px; height: 28px; border-radius: 50%;
  background: var(--gray-100); display: flex; align-items: center;
  justify-content: center; font-size: 1.25rem; transition: all var(--transition);
  flex-shrink: 0;
}
.faq__item.active .faq__icon { background: var(--lime); transform: rotate(45deg); }
.faq__answer {
  max-height: 0; overflow: hidden; transition: max-height .4s ease, padding .4s ease;
}
.faq__item.active .faq__answer { max-height: 300px; padding-bottom: 24px; }
.faq__answer p { font-size: .938rem; color: var(--gray-600); line-height: 1.7; }

/* ===== CTA BANNER ===== */
.cta-banner {
  background: var(--black); padding: 80px 0; text-align: center;
  position: relative; overflow: hidden;
}
.cta-banner::before {
  content: ''; position: absolute; top: -100px; left: 50%;
  transform: translateX(-50%); width: 600px; height: 600px;
  border-radius: 50%; background: radial-gradient(circle, rgba(230,255,50,.08) 0%, transparent 60%);
  pointer-events: none;
}
.cta-banner__title { color: var(--white); margin-bottom: 16px; position: relative; z-index: 1; }
.cta-banner__subtitle { color: rgba(255,255,255,.6); font-size: 1.125rem; margin-bottom: 32px; max-width: 560px; margin-left: auto; margin-right: auto; position: relative; z-index: 1; }

/* ===== SOCIAL PROOF ===== */
.social-proof { text-align: center; }
.social-proof__logos { display: flex; flex-wrap: wrap; justify-content: center; gap: 40px; align-items: center; margin-top: 40px; }
.social-proof__logo { font-size: 1.25rem; font-weight: 800; color: var(--gray-300); transition: color var(--transition); }
.social-proof__logo:hover { color: var(--gray-600); }

/* ===== FOOTER ===== */
.footer { background: var(--gray-900); padding: 64px 0 32px; color: rgba(255,255,255,.6); }
.footer__grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 48px; }
.footer__brand-desc { font-size: .875rem; line-height: 1.7; margin-top: 16px; max-width: 280px; }
.footer__logo { font-family: 'Plus Jakarta Sans', sans-serif; font-weight: 800; font-size: 1.25rem; color: var(--white); display: flex; align-items: center; gap: 8px; }
.footer__col-title { font-weight: 700; font-size: .875rem; color: var(--white); margin-bottom: 16px; text-transform: uppercase; letter-spacing: .05em; }
.footer__link { display: block; font-size: .875rem; color: rgba(255,255,255,.5); margin-bottom: 10px; transition: color var(--transition); }
.footer__link:hover { color: var(--lime); }
.footer__bottom { border-top: 1px solid rgba(255,255,255,.1); padding-top: 24px; display: flex; justify-content: space-between; align-items: center; font-size: .813rem; }

/* ===== FEATURE CARDS (shared) ===== */
.feature-cards__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.feature-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.feature-card__icon {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px; font-size: 1.25rem;
}
.feature-card__icon--blue { background: #EEF2FF; color: #4F46E5; }
.feature-card__icon--green { background: #ECFDF5; color: #059669; }
.feature-card__icon--orange { background: #FFF7ED; color: #EA580C; }
.feature-card__icon--pink { background: #FDF2F8; color: #DB2777; }
.feature-card__title { margin-bottom: 12px; }
.feature-card__desc { font-size: .938rem; color: var(--gray-500); line-height: 1.6; }

/* ===== PRODUCT DEMO (accordion) ===== */
.product-demo__item { border: 1px solid var(--gray-200); border-radius: var(--radius-md); margin-bottom: 12px; overflow: hidden; }
.product-demo__header {
  width: 100%; padding: 20px 24px; text-align: left;
  font-weight: 600; font-size: 1rem; display: flex;
  justify-content: space-between; align-items: center;
  background: var(--white); transition: background var(--transition);
}
.product-demo__header:hover { background: var(--gray-50); }
.product-demo__item.active .product-demo__header { background: var(--gray-50); }
.product-demo__arrow { transition: transform var(--transition); font-size: 1.25rem; }
.product-demo__item.active .product-demo__arrow { transform: rotate(180deg); }
.product-demo__body { max-height: 0; overflow: hidden; transition: max-height .4s ease; }
.product-demo__item.active .product-demo__body { max-height: 400px; }
.product-demo__content { padding: 0 24px 24px; font-size: .938rem; color: var(--gray-600); line-height: 1.7; }

/* ===== TOOLS GRID ===== */
.tools-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }
.tools-grid__category { margin-bottom: 32px; }
.tools-grid__category-title {
  font-size: .75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: .08em; color: var(--gray-400); margin-bottom: 12px;
}
.tools-grid__items { display: flex; flex-wrap: wrap; gap: 8px; }
.tools-grid__tag {
  padding: 8px 16px; border-radius: 50px;
  background: var(--gray-100); font-size: .813rem;
  font-weight: 500; color: var(--gray-700);
  transition: all var(--transition);
}
.tools-grid__tag:hover { background: var(--lime); color: var(--black); }

/* ===== STEPS ===== */
.steps__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; position: relative; }
.steps__grid::before {
  content: ''; position: absolute; top: 40px; left: 16.67%; right: 16.67%;
  height: 2px; background: var(--gray-200);
}
.step-card { text-align: center; position: relative; z-index: 1; }
.step-card__number {
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--lime); color: var(--black);
  display: flex; align-items: center; justify-content: center;
  font-weight: 800; font-size: 1.25rem; margin: 0 auto 20px;
}
.step-card__title { margin-bottom: 12px; }
.step-card__desc { font-size: .938rem; color: var(--gray-500); line-height: 1.6; }

/* ===== COACHING SPOTLIGHT ===== */
.spotlight__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.spotlight-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.spotlight-card__name { font-size: 1.25rem; font-weight: 700; margin-bottom: 8px; }
.spotlight-card__desc { font-size: .938rem; color: var(--gray-500); line-height: 1.6; }

/* ===== RESOURCES ===== */
.resources__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.resource-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 28px; border: 1px solid var(--gray-200);
  display: flex; align-items: flex-start; gap: 16px;
  transition: all var(--transition);
}
.resource-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.resource-card__icon {
  flex-shrink: 0; width: 44px; height: 44px;
  border-radius: var(--radius-sm); background: var(--lime);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem; color: var(--black);
}
.resource-card__title { font-weight: 600; font-size: .938rem; margin-bottom: 4px; }
.resource-card__desc { font-size: .813rem; color: var(--gray-500); line-height: 1.5; }

/* ===== FILE TYPES ===== */
.file-types__grid { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.file-type-tag {
  padding: 12px 24px; border-radius: 50px;
  background: var(--gray-100); font-weight: 500;
  font-size: .875rem; color: var(--gray-700);
  transition: all var(--transition);
}
.file-type-tag:hover { background: var(--lime); color: var(--black); }

/* ===== VALUE PROPOSITION ===== */
.value-props__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.value-prop-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.value-prop-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.value-prop-card__icon { width: 48px; height: 48px; border-radius: var(--radius-md); background: var(--lime); display: flex; align-items: center; justify-content: center; font-size: 1.25rem; margin-bottom: 20px; }
.value-prop-card__title { margin-bottom: 12px; }
.value-prop-card__desc { font-size: .938rem; color: var(--gray-500); line-height: 1.6; }

/* ===== BUSINESS FIT ===== */
.business-fit__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 24px; }
.business-fit-card {
  text-align: center; padding: 32px; background: var(--gray-50);
  border-radius: var(--radius-lg); transition: all var(--transition);
}
.business-fit-card:hover { background: var(--lime); }
.business-fit-card__icon { font-size: 2rem; margin-bottom: 16px; }
.business-fit-card__title { font-weight: 700; margin-bottom: 8px; }
.business-fit-card__desc { font-size: .875rem; color: var(--gray-500); line-height: 1.5; }

/* ===== MEMBERSHIP MANAGEMENT ===== */
.management__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.management-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.management-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.management-card__stat { font-size: 2.5rem; font-weight: 800; color: var(--lime); margin-bottom: 8px; }

/* ===== SECTION HEADERS ===== */
.section__header { text-align: center; margin-bottom: 48px; }
.section__header h2 { margin-bottom: 16px; }
.section__header p { font-size: 1.125rem; color: var(--gray-500); max-width: 600px; margin: 0 auto; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .footer__grid { grid-template-columns: 1fr 1fr 1fr; }
  .testimonial-card { flex: 0 0 calc(50% - 12px); }
}
@media (max-width: 768px) {
  .section { padding: 60px 0; }
  .navbar__links { display: none; }
  .navbar__links.active {
    display: flex; flex-direction: column;
    position: absolute; top: 72px; left: 0; right: 0;
    background: var(--white); padding: 24px;
    border-bottom: 1px solid var(--gray-200);
    gap: 16px; box-shadow: var(--shadow-lg);
  }
  .navbar__mobile-toggle { display: flex; }
  .stats-bar__grid { grid-template-columns: 1fr; gap: 24px; }
  .hero__preview-grid { grid-template-columns: 1fr; }
  .hero__preview-sidebar { border-right: none; border-bottom: 1px solid var(--gray-200); padding-bottom: 16px; padding-right: 0; }
  .steps__grid { grid-template-columns: 1fr; }
  .steps__grid::before { display: none; }
  .testimonial-card { flex: 0 0 calc(100% - 0px); min-width: 0; }
  .pricing__grid { grid-template-columns: 1fr; max-width: 400px; margin-left: auto; margin-right: auto; }
  .footer__grid { grid-template-columns: 1fr 1fr; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
  .why-choose__tabs { gap: 6px; }
  .why-choose__tab-btn { padding: 8px 16px; font-size: .813rem; }
}
@media (max-width: 480px) {
  .hero__actions { flex-direction: column; align-items: center; }
  .footer__grid { grid-template-columns: 1fr; }
  .products__grid { grid-template-columns: 1fr; }
}

/* ===== RESET & BASE ===== */
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,.1), 0 2px 4px -2px rgba(0,0,0,.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,.1), 0 4px 6px -4px rgba(0,0,0,.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,.1), 0 8px 10px -6px rgba(0,0,0,.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: .3s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: 'Inter', 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4 { font-family: 'Plus Jakarta Sans', 'Inter', sans-serif; font-weight: 700; line-height: 1.15; }
h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); }
h4 { font-size: 1.125rem; }

/* ===== LAYOUT ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section--gray { background: var(--gray-50); }

/* ===== ANIMATIONS ===== */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slideIn {
  from { opacity: 0; transform: translateX(20px); }
  to { opacity: 1; transform: translateX(0); }
}
.animate-on-scroll { opacity: 0; transform: translateY(30px); transition: opacity .6s ease, transform .6s ease; }
.animate-on-scroll.visible { opacity: 1; transform: translateY(0); }

/* ===== NAVBAR ===== */
.navbar {
  position: sticky; top: 0; z-index: 1000;
  background: rgba(255,255,255,.95); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.navbar.scrolled { box-shadow: var(--shadow-md); }
.navbar__inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 72px; max-width: 1200px; margin: 0 auto; padding: 0 24px;
}
.navbar__logo {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800; font-size: 1.5rem; color: var(--black);
  display: flex; align-items: center; gap: 8px;
}
.navbar__logo-icon {
  width: 36px; height: 36px; background: var(--lime);
  border-radius: 8px; display: flex; align-items: center; justify-content: center;
  font-weight: 900; color: var(--black); font-size: 1.2rem;
}
.navbar__links { display: flex; align-items: center; gap: 32px; }
.navbar__link {
  font-size: .938rem; font-weight: 500; color: var(--gray-600);
  transition: color var(--transition); position: relative;
}
.navbar__link:hover { color: var(--black); }
.navbar__link::after {
  content: ''; position: absolute; bottom: -4px; left: 0;
  width: 0; height: 2px; background: var(--lime);
  transition: width var(--transition);
}
.navbar__link:hover::after { width: 100%; }
.navbar__cta {
  background: var(--black); color: var(--white);
  padding: 10px 24px; border-radius: 50px;
  font-weight: 600; font-size: .875rem;
  transition: all var(--transition);
  display: inline-flex; align-items: center; gap: 6px;
}
.navbar__cta:hover { background: var(--burgundy); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.navbar__mobile-toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.navbar__mobile-toggle span { display: block; width: 24px; height: 2px; background: var(--black); transition: var(--transition); border-radius: 2px; }

/* ===== HERO ===== */
.hero {
  padding: 80px 0 60px;
  background: linear-gradient(180deg, var(--white) 0%, var(--gray-50) 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: -200px; right: -200px;
  width: 600px; height: 600px; border-radius: 50%;
  background: radial-gradient(circle, rgba(230,255,50,.12) 0%, transparent 70%);
  pointer-events: none;
}
.hero__content { text-align: center; max-width: 800px; margin: 0 auto 48px; position: relative; z-index: 1; }
.hero__title { margin-bottom: 20px; color: var(--black); }
.hero__title span { color: var(--burgundy); }
.hero__subtitle { font-size: clamp(1rem, 2vw, 1.25rem); color: var(--gray-600); margin-bottom: 32px; max-width: 640px; margin-left: auto; margin-right: auto; }
.hero__actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 32px; border-radius: 50px;
  font-weight: 600; font-size: 1rem;
  transition: all var(--transition);
}
.btn--primary { background: var(--black); color: var(--white); }
.btn--primary:hover { background: var(--burgundy); transform: translateY(-2px); box-shadow: var(--shadow-xl); }
.btn--secondary { background: var(--white); color: var(--black); border: 2px solid var(--gray-200); }
.btn--secondary:hover { border-color: var(--black); transform: translateY(-2px); }
.btn--lime { background: var(--lime); color: var(--black); }
.btn--lime:hover { background: #d4eb2e; transform: translateY(-2px); box-shadow: var(--shadow-lg); }

/* Hero Tab Switch */
.hero__tabs { margin-top: 40px; }
.hero__tab-nav { display: flex; justify-content: center; gap: 8px; margin-bottom: 24px; }
.hero__tab-btn {
  padding: 10px 28px; border-radius: 50px;
  font-weight: 600; font-size: .875rem;
  background: var(--white); color: var(--gray-600);
  border: 2px solid var(--gray-200);
  transition: all var(--transition);
}
.hero__tab-btn.active { background: var(--black); color: var(--white); border-color: var(--black); }
.hero__tab-btn:hover:not(.active) { border-color: var(--gray-400); }
.hero__tab-panel { display: none; animation: fadeIn .4s ease; }
.hero__tab-panel.active { display: block; }
.hero__preview {
  background: var(--white); border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200); box-shadow: var(--shadow-xl);
  overflow: hidden; max-width: 900px; margin: 0 auto;
}
.hero__preview-header {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 20px; background: var(--gray-50);
  border-bottom: 1px solid var(--gray-200);
}
.hero__preview-dot { width: 10px; height: 10px; border-radius: 50%; }
.hero__preview-dot--red { background: #EF4444; }
.hero__preview-dot--yellow { background: #F59E0B; }
.hero__preview-dot--green { background: #10B981; }
.hero__preview-body { padding: 32px; min-height: 280px; }
.hero__preview-grid { display: grid; grid-template-columns: 220px 1fr; gap: 24px; }
.hero__preview-sidebar { border-right: 1px solid var(--gray-200); padding-right: 24px; }
.hero__preview-sidebar-item {
  padding: 10px 12px; border-radius: var(--radius-sm);
  font-size: .813rem; color: var(--gray-600); margin-bottom: 4px;
  transition: all var(--transition); cursor: pointer;
}
.hero__preview-sidebar-item.active { background: var(--lime); color: var(--black); font-weight: 600; }
.hero__preview-main h4 { font-size: 1rem; margin-bottom: 12px; }
.hero__preview-main p { font-size: .813rem; color: var(--gray-500); line-height: 1.6; }
.hero__preview-student { text-align: center; }
.hero__preview-student h4 { font-size: 1.25rem; margin-bottom: 16px; }
.hero__preview-progress { background: var(--gray-100); border-radius: 50px; height: 8px; margin: 16px 0; overflow: hidden; }
.hero__preview-progress-bar { height: 100%; background: var(--lime); border-radius: 50px; width: 65%; }

/* ===== STATS BAR ===== */
.stats-bar {
  background: var(--black); padding: 48px 0;
}
.stats-bar__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; text-align: center; }
.stats-bar__item { animation: fadeUp .6s ease both; }
.stats-bar__number {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(2rem, 4vw, 3.5rem); font-weight: 800;
  color: var(--lime); margin-bottom: 8px;
}
.stats-bar__label { font-size: 1rem; color: rgba(255,255,255,.7); font-weight: 500; }

/* ===== PRODUCTS ===== */
.products__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 24px; }
.product-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition); position: relative; overflow: hidden;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); border-color: transparent; }
.product-card__icon {
  width: 56px; height: 56px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; margin-bottom: 20px;
}
.product-card__icon--courses { background: #EEF2FF; color: #4F46E5; }
.product-card__icon--coaching { background: #FEF3C7; color: #D97706; }
.product-card__icon--downloads { background: #ECFDF5; color: #059669; }
.product-card__icon--memberships { background: #FDF2F8; color: #DB2777; }
.product-card__title { margin-bottom: 12px; }
.product-card__desc { color: var(--gray-500); font-size: .938rem; line-height: 1.6; margin-bottom: 20px; }
.product-card__link {
  font-weight: 600; font-size: .875rem; color: var(--black);
  display: inline-flex; align-items: center; gap: 6px;
  transition: gap var(--transition);
}
.product-card__link:hover { gap: 10px; }
.product-card::after {
  content: ''; position: absolute; top: 0; left: 0;
  width: 100%; height: 3px; background: var(--lime);
  transform: scaleX(0); transform-origin: left;
  transition: transform var(--transition);
}
.product-card:hover::after { transform: scaleX(1); }

/* ===== WHY CHOOSE US (Tabs) ===== */
.why-choose__tabs { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 48px; }
.why-choose__tab-btn {
  padding: 12px 24px; border-radius: 50px;
  font-weight: 600; font-size: .875rem;
  background: var(--white); color: var(--gray-600);
  border: 2px solid var(--gray-200);
  transition: all var(--transition);
}
.why-choose__tab-btn.active { background: var(--lime); color: var(--black); border-color: var(--lime); }
.why-choose__tab-btn:hover:not(.active) { border-color: var(--gray-400); color: var(--black); }
.why-choose__panel { display: none; animation: fadeIn .4s ease; }
.why-choose__panel.active { display: block; }
.why-choose__features { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 20px; }
.why-choose__feature {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 16px; border-radius: var(--radius-md);
  background: var(--gray-50); transition: all var(--transition);
}
.why-choose__feature:hover { background: var(--lime); }
.why-choose__feature-icon { flex-shrink: 0; width: 24px; height: 24px; color: var(--burgundy); }
.why-choose__feature-text { font-weight: 500; font-size: .938rem; }

/* ===== GLOBAL SCALE ===== */
.global-scale { text-align: center; }
.global-scale__map {
  width: 100%; max-width: 800px; margin: 40px auto;
  position: relative; height: 300px;
  background: var(--gray-100); border-radius: var(--radius-lg);
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.global-scale__map-text { font-size: 1.5rem; font-weight: 700; color: var(--gray-400); }
.global-scale__dots { display: flex; flex-wrap: wrap; justify-content: center; gap: 16px; margin-top: 32px; }
.global-scale__dot-item {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 20px; background: var(--white);
  border: 1px solid var(--gray-200); border-radius: 50px;
  font-size: .875rem; font-weight: 500;
}
.global-scale__dot-indicator { width: 8px; height: 8px; border-radius: 50%; background: var(--lime); }

/* ===== AI AUTOMATIONS ===== */
.ai-automations__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.ai-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.ai-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.ai-card__badge {
  display: inline-block; padding: 4px 12px; border-radius: 50px;
  background: var(--lime); color: var(--black);
  font-size: .75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: .05em; margin-bottom: 16px;
}
.ai-card__title { margin-bottom: 12px; }
.ai-card__desc { color: var(--gray-500); font-size: .938rem; line-height: 1.6; }

/* ===== TESTIMONIALS ===== */
.testimonials { overflow: hidden; }
.testimonials__header { text-align: center; margin-bottom: 48px; }
.testimonials__carousel { position: relative; }
.testimonials__track {
  display: flex; gap: 24px;
  transition: transform .5s cubic-bezier(.4,0,.2,1);
}
.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  min-height: 260px; display: flex; flex-direction: column;
  transition: all var(--transition);
}
.testimonial-card:hover { box-shadow: var(--shadow-lg); }
.testimonial-card__quote {
  font-size: .938rem; color: var(--gray-600); line-height: 1.7;
  flex: 1; margin-bottom: 20px; position: relative;
}
.testimonial-card__quote::before {
  content: '\201C'; font-size: 3rem; color: var(--lime);
  position: absolute; top: -16px; left: -4px;
  font-family: Georgia, serif; line-height: 1;
}
.testimonial-card__quote p { padding-left: 20px; }
.testimonial-card__author { display: flex; align-items: center; gap: 12px; }
.testimonial-card__avatar {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: .875rem; color: var(--gray-500);
}
.testimonial-card__name { font-weight: 600; font-size: .875rem; }
.testimonial-card__role { font-size: .813rem; color: var(--gray-400); }
.testimonials__nav { display: flex; justify-content: center; gap: 12px; margin-top: 32px; }
.testimonials__nav-btn {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); border: 2px solid var(--gray-200);
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition); font-size: 1.2rem; color: var(--gray-600);
}
.testimonials__nav-btn:hover { background: var(--black); color: var(--white); border-color: var(--black); }

/* ===== PRICING ===== */
.pricing__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 20px; }
.pricing-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 2px solid var(--gray-200);
  transition: all var(--transition); position: relative;
}
.pricing-card--featured { border-color: var(--lime); }
.pricing-card--featured::before {
  content: 'Most Popular'; position: absolute; top: -12px; left: 50%;
  transform: translateX(-50%); background: var(--lime);
  padding: 4px 16px; border-radius: 50px;
  font-size: .75rem; font-weight: 700; color: var(--black);
}
.pricing-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.pricing-card__name { font-size: 1.125rem; font-weight: 700; margin-bottom: 8px; }
.pricing-card__price { font-size: 2.5rem; font-weight: 800; margin-bottom: 4px; }
.pricing-card__price span { font-size: 1rem; font-weight: 400; color: var(--gray-500); }
.pricing-card__fee { font-size: .813rem; color: var(--gray-400); margin-bottom: 20px; }
.pricing-card__features { margin-bottom: 24px; }
.pricing-card__feature {
  display: flex; align-items: flex-start; gap: 10px;
  font-size: .875rem; color: var(--gray-600);
  margin-bottom: 10px; line-height: 1.5;
}
.pricing-card__check { flex-shrink: 0; color: var(--lime); font-weight: 700; font-size: 1rem; }
.pricing-card__btn {
  width: 100%; padding: 12px; border-radius: 50px;
  font-weight: 600; font-size: .875rem; text-align: center;
  transition: all var(--transition);
}
.pricing-card__btn--primary { background: var(--black); color: var(--white); }
.pricing-card__btn--primary:hover { background: var(--burgundy); }
.pricing-card__btn--lime { background: var(--lime); color: var(--black); }
.pricing-card__btn--lime:hover { background: #d4eb2e; }
.pricing__note { text-align: center; margin-top: 32px; font-size: .875rem; color: var(--gray-500); }

/* ===== INTEGRATIONS ===== */
.integrations__header { text-align: center; margin-bottom: 48px; }
.integrations__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 16px; }
.integration-item {
  display: flex; flex-direction: column; align-items: center;
  gap: 10px; padding: 24px 16px; background: var(--white);
  border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  transition: all var(--transition);
}
.integration-item:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: var(--gray-300); }
.integration-item__logo {
  width: 48px; height: 48px; border-radius: var(--radius-sm);
  background: var(--gray-50); display: flex; align-items: center;
  justify-content: center; font-weight: 800; font-size: .75rem;
  color: var(--gray-600);
}
.integration-item__name { font-size: .813rem; font-weight: 600; color: var(--gray-700); text-align: center; }

/* ===== FAQ ===== */
.faq__list { max-width: 760px; margin: 0 auto; }
.faq__item {
  border-bottom: 1px solid var(--gray-200);
  overflow: hidden;
}
.faq__question {
  width: 100%; text-align: left; padding: 24px 0;
  font-size: 1.063rem; font-weight: 600; color: var(--gray-900);
  display: flex; justify-content: space-between; align-items: center;
  transition: color var(--transition);
}
.faq__question:hover { color: var(--burgundy); }
.faq__icon {
  width: 28px; height: 28px; border-radius: 50%;
  background: var(--gray-100); display: flex; align-items: center;
  justify-content: center; font-size: 1.25rem; transition: all var(--transition);
  flex-shrink: 0;
}
.faq__item.active .faq__icon { background: var(--lime); transform: rotate(45deg); }
.faq__answer {
  max-height: 0; overflow: hidden; transition: max-height .4s ease, padding .4s ease;
}
.faq__item.active .faq__answer { max-height: 300px; padding-bottom: 24px; }
.faq__answer p { font-size: .938rem; color: var(--gray-600); line-height: 1.7; }

/* ===== CTA BANNER ===== */
.cta-banner {
  background: var(--black); padding: 80px 0; text-align: center;
  position: relative; overflow: hidden;
}
.cta-banner::before {
  content: ''; position: absolute; top: -100px; left: 50%;
  transform: translateX(-50%); width: 600px; height: 600px;
  border-radius: 50%; background: radial-gradient(circle, rgba(230,255,50,.08) 0%, transparent 60%);
  pointer-events: none;
}
.cta-banner__title { color: var(--white); margin-bottom: 16px; position: relative; z-index: 1; }
.cta-banner__subtitle { color: rgba(255,255,255,.6); font-size: 1.125rem; margin-bottom: 32px; max-width: 560px; margin-left: auto; margin-right: auto; position: relative; z-index: 1; }

/* ===== SOCIAL PROOF ===== */
.social-proof { text-align: center; }
.social-proof__logos { display: flex; flex-wrap: wrap; justify-content: center; gap: 40px; align-items: center; margin-top: 40px; }
.social-proof__logo { font-size: 1.25rem; font-weight: 800; color: var(--gray-300); transition: color var(--transition); }
.social-proof__logo:hover { color: var(--gray-600); }

/* ===== FOOTER ===== */
.footer { background: var(--gray-900); padding: 64px 0 32px; color: rgba(255,255,255,.6); }
.footer__grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 48px; }
.footer__brand-desc { font-size: .875rem; line-height: 1.7; margin-top: 16px; max-width: 280px; }
.footer__logo { font-family: 'Plus Jakarta Sans', sans-serif; font-weight: 800; font-size: 1.25rem; color: var(--white); display: flex; align-items: center; gap: 8px; }
.footer__col-title { font-weight: 700; font-size: .875rem; color: var(--white); margin-bottom: 16px; text-transform: uppercase; letter-spacing: .05em; }
.footer__link { display: block; font-size: .875rem; color: rgba(255,255,255,.5); margin-bottom: 10px; transition: color var(--transition); }
.footer__link:hover { color: var(--lime); }
.footer__bottom { border-top: 1px solid rgba(255,255,255,.1); padding-top: 24px; display: flex; justify-content: space-between; align-items: center; font-size: .813rem; }

/* ===== FEATURE CARDS (shared) ===== */
.feature-cards__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.feature-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.feature-card__icon {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px; font-size: 1.25rem;
}
.feature-card__icon--blue { background: #EEF2FF; color: #4F46E5; }
.feature-card__icon--green { background: #ECFDF5; color: #059669; }
.feature-card__icon--orange { background: #FFF7ED; color: #EA580C; }
.feature-card__icon--pink { background: #FDF2F8; color: #DB2777; }
.feature-card__title { margin-bottom: 12px; }
.feature-card__desc { font-size: .938rem; color: var(--gray-500); line-height: 1.6; }

/* ===== PRODUCT DEMO (accordion) ===== */
.product-demo__item { border: 1px solid var(--gray-200); border-radius: var(--radius-md); margin-bottom: 12px; overflow: hidden; }
.product-demo__header {
  width: 100%; padding: 20px 24px; text-align: left;
  font-weight: 600; font-size: 1rem; display: flex;
  justify-content: space-between; align-items: center;
  background: var(--white); transition: background var(--transition);
}
.product-demo__header:hover { background: var(--gray-50); }
.product-demo__item.active .product-demo__header { background: var(--gray-50); }
.product-demo__arrow { transition: transform var(--transition); font-size: 1.25rem; }
.product-demo__item.active .product-demo__arrow { transform: rotate(180deg); }
.product-demo__body { max-height: 0; overflow: hidden; transition: max-height .4s ease; }
.product-demo__item.active .product-demo__body { max-height: 400px; }
.product-demo__content { padding: 0 24px 24px; font-size: .938rem; color: var(--gray-600); line-height: 1.7; }

/* ===== TOOLS GRID ===== */
.tools-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; }
.tools-grid__category { margin-bottom: 32px; }
.tools-grid__category-title {
  font-size: .75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: .08em; color: var(--gray-400); margin-bottom: 12px;
}
.tools-grid__items { display: flex; flex-wrap: wrap; gap: 8px; }
.tools-grid__tag {
  padding: 8px 16px; border-radius: 50px;
  background: var(--gray-100); font-size: .813rem;
  font-weight: 500; color: var(--gray-700);
  transition: all var(--transition);
}
.tools-grid__tag:hover { background: var(--lime); color: var(--black); }

/* ===== STEPS ===== */
.steps__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; position: relative; }
.steps__grid::before {
  content: ''; position: absolute; top: 40px; left: 16.67%; right: 16.67%;
  height: 2px; background: var(--gray-200);
}
.step-card { text-align: center; position: relative; z-index: 1; }
.step-card__number {
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--lime); color: var(--black);
  display: flex; align-items: center; justify-content: center;
  font-weight: 800; font-size: 1.25rem; margin: 0 auto 20px;
}
.step-card__title { margin-bottom: 12px; }
.step-card__desc { font-size: .938rem; color: var(--gray-500); line-height: 1.6; }

/* ===== COACHING SPOTLIGHT ===== */
.spotlight__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.spotlight-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.spotlight-card__name { font-size: 1.25rem; font-weight: 700; margin-bottom: 8px; }
.spotlight-card__desc { font-size: .938rem; color: var(--gray-500); line-height: 1.6; }

/* ===== RESOURCES ===== */
.resources__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.resource-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 28px; border: 1px solid var(--gray-200);
  display: flex; align-items: flex-start; gap: 16px;
  transition: all var(--transition);
}
.resource-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.resource-card__icon {
  flex-shrink: 0; width: 44px; height: 44px;
  border-radius: var(--radius-sm); background: var(--lime);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem; color: var(--black);
}
.resource-card__title { font-weight: 600; font-size: .938rem; margin-bottom: 4px; }
.resource-card__desc { font-size: .813rem; color: var(--gray-500); line-height: 1.5; }

/* ===== FILE TYPES ===== */
.file-types__grid { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.file-type-tag {
  padding: 12px 24px; border-radius: 50px;
  background: var(--gray-100); font-weight: 500;
  font-size: .875rem; color: var(--gray-700);
  transition: all var(--transition);
}
.file-type-tag:hover { background: var(--lime); color: var(--black); }

/* ===== VALUE PROPOSITION ===== */
.value-props__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.value-prop-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.value-prop-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.value-prop-card__icon { width: 48px; height: 48px; border-radius: var(--radius-md); background: var(--lime); display: flex; align-items: center; justify-content: center; font-size: 1.25rem; margin-bottom: 20px; }
.value-prop-card__title { margin-bottom: 12px; }
.value-prop-card__desc { font-size: .938rem; color: var(--gray-500); line-height: 1.6; }

/* ===== BUSINESS FIT ===== */
.business-fit__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 24px; }
.business-fit-card {
  text-align: center; padding: 32px; background: var(--gray-50);
  border-radius: var(--radius-lg); transition: all var(--transition);
}
.business-fit-card:hover { background: var(--lime); }
.business-fit-card__icon { font-size: 2rem; margin-bottom: 16px; }
.business-fit-card__title { font-weight: 700; margin-bottom: 8px; }
.business-fit-card__desc { font-size: .875rem; color: var(--gray-500); line-height: 1.5; }

/* ===== MEMBERSHIP MANAGEMENT ===== */
.management__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
.management-card {
  background: var(--white); border-radius: var(--radius-lg);
  padding: 32px; border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.management-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.management-card__stat { font-size: 2.5rem; font-weight: 800; color: var(--lime); margin-bottom: 8px; }

/* ===== SECTION HEADERS ===== */
.section__header { text-align: center; margin-bottom: 48px; }
.section__header h2 { margin-bottom: 16px; }
.section__header p { font-size: 1.125rem; color: var(--gray-500); max-width: 600px; margin: 0 auto; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .footer__grid { grid-template-columns: 1fr 1fr 1fr; }
  .testimonial-card { flex: 0 0 calc(50% - 12px); }
}
@media (max-width: 768px) {
  .section { padding: 60px 0; }
  .navbar__links { display: none; }
  .navbar__links.active {
    display: flex; flex-direction: column;
    position: absolute; top: 72px; left: 0; right: 0;
    background: var(--white); padding: 24px;
    border-bottom: 1px solid var(--gray-200);
    gap: 16px; box-shadow: var(--shadow-lg);
  }
  .navbar__mobile-toggle { display: flex; }
  .stats-bar__grid { grid-template-columns: 1fr; gap: 24px; }
  .hero__preview-grid { grid-template-columns: 1fr; }
  .hero__preview-sidebar { border-right: none; border-bottom: 1px solid var(--gray-200); padding-bottom: 16px; padding-right: 0; }
  .steps__grid { grid-template-columns: 1fr; }
  .steps__grid::before { display: none; }
  .testimonial-card { flex: 0 0 calc(100% - 0px); min-width: 0; }
  .pricing__grid { grid-template-columns: 1fr; max-width: 400px; margin-left: auto; margin-right: auto; }
  .footer__grid { grid-template-columns: 1fr 1fr; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
  .why-choose__tabs { gap: 6px; }
  .why-choose__tab-btn { padding: 8px 16px; font-size: .813rem; }
}
@media (max-width: 480px) {
  .hero__actions { flex-direction: column; align-items: center; }
  .footer__grid { grid-template-columns: 1fr; }
  .products__grid { grid-template-columns: 1fr; }
}

